        m=re.findall(r'IC\s*8\s*-\s*1\s*-\s*26\s*-\s*([^\n]*)',p)
        if len(m)!=1: bad.append((f,i,m,p[:300].replace('\n','|')));continue
        n+=1
        s=re.sub(r'\((?:[A-Za-z][A-Za-z-]+)\)','',m[0]).strip().replace(' ','')
        c[s]+=1
print(n,len(bad));
for b in bad:print(b)
for k,v in c.most_common():print(repr(k),v)
print(c['16(h)']/n*100,c['20(a)(2)']/n*100)
